<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Bouncing Balls in Rotating Hexagon</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      background: #11141a;
      overflow: hidden;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
<canvas id="canvas"></canvas>

<script>
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');

  let width, height, cx, cy, hexRadius;
  function resize() {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
    cx = width / 2;
    cy = height / 2;
    hexRadius = Math.min(width, height) * 0.42;
  }
  window.addEventListener('resize', resize);
  resize();

  // Hexagon parameters
  let hexAngle = 0;
  const hexSpeed = 0.4; // rad/s rotation speed

  // Physics constants
  const GRAVITY = 980; // px/s^2
  const AIR_RESISTANCE = 0.9995;
  const BALL_RESTITUTION = 0.78;
  const WALL_RESTITUTION = 0.75;
  const WALL_FRICTION = 0.05;

  // 10 balls with distinct vibrant colors
  const colors = [
    '#ff3b30', '#ff9500', '#ffd60a', '#34c759', '#00c7be',
    '#30b0c7', '#007aff', '#5856d6', '#af52de', '#ff2d55'
  ];

  class Ball {
    constructor(x, y, radius, color) {
      this.x = x;
      this.y = y;
      this.vx = (Math.random() - 0.5) * 100;
      this.vy = (Math.random() - 0.5) * 100;
      this.radius = radius;
      this.mass = radius * radius;
      this.color = color;
    }

    draw() {
      const grad = ctx.createRadialGradient(
        this.x - this.radius * 0.3,
        this.y - this.radius * 0.3,
        this.radius * 0.1,
        this.x,
        this.y,
        this.radius
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.3, this.color);
      grad.addColorStop(1, '#000000');

      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.closePath();
    }
  }

  // Initialize balls spread across the center area
  const balls = [];
  const BALL_RADIUS = Math.min(width, height) * 0.024;
  for (let i = 0; i < 10; i++) {
    const angle = (i / 10) * Math.PI * 2;
    const dist = (i % 3 + 1) * 35;
    balls.push(new Ball(
      cx + Math.cos(angle) * dist,
      cy + Math.sin(angle) * dist,
      BALL_RADIUS,
      colors[i]
    ));
  }

  function getHexagonVertices(angle) {
    const vertices = [];
    for (let i = 0; i < 6; i++) {
      const a = angle + (i * Math.PI) / 3;
      vertices.push({
        x: cx + hexRadius * Math.cos(a),
        y: cy + hexRadius * Math.sin(a)
      });
    }
    return vertices;
  }

  // Find closest point on line segment AB to point P
  function closestPointOnSegment(px, py, ax, ay, bx, by) {
    const abx = bx - ax;
    const aby = by - ay;
    const lenSq = abx * abx + aby * aby;
    if (lenSq === 0) return { x: ax, y: ay, t: 0 };
    const apx = px - ax;
    const apy = py - ay;
    let t = (apx * abx + apy * aby) / lenSq;
    t = Math.max(0, Math.min(1, t));
    return { x: ax + t * abx, y: ay + t * aby, t };
  }

  let lastTime = performance.now();

  function update() {
    const now = performance.now();
    let dt = (now - lastTime) / 1000;
    lastTime = now;
    if (dt > 0.05) dt = 0.05; // Prevent large delta jumps

    // Sub-stepping for stable continuous physics
    const subSteps = 8;
    const subDt = dt / subSteps;

    for (let step = 0; step < subSteps; step++) {
      hexAngle += hexSpeed * subDt;
      const vertices = getHexagonVertices(hexAngle);

      // Integrate velocity and gravity
      for (const b of balls) {
        b.vy += GRAVITY * subDt;
        b.vx *= Math.pow(AIR_RESISTANCE, subDt * 60);
        b.vy *= Math.pow(AIR_RESISTANCE, subDt * 60);
        b.x += b.vx * subDt;
        b.y += b.vy * subDt;
      }

      // Ball-to-wall collisions
      for (const b of balls) {
        for (let i = 0; i < 6; i++) {
          const v1 = vertices[i];
          const v2 = vertices[(i + 1) % 6];
          const pt = closestPointOnSegment(b.x, b.y, v1.x, v1.y, v2.x, v2.y);

          let dx = b.x - pt.x;
          let dy = b.y - pt.y;
          let dist = Math.hypot(dx, dy);

          if (dist < b.radius) {
            // Normal pointing into the hexagon
            let nx = dx / (dist || 1);
            let ny = dy / (dist || 1);

            // Positional correction
            const penetration = b.radius - dist;
            b.x += nx * penetration;
            b.y += ny * penetration;

            // Linear velocity of rotating wall at contact point (v = omega x r)
            const rx = pt.x - cx;
            const ry = pt.y - cy;
            const wallVx = -hexSpeed * ry;
            const wallVy = hexSpeed * rx;

            // Ball velocity relative to moving wall
            const relVx = b.vx - wallVx;
            const relVy = b.vy - wallVy;
            const normalVel = relVx * nx + relVy * ny;

            if (normalVel < 0) {
              // Elastic bounce
              const impulseNormal = -(1 + WALL_RESTITUTION) * normalVel;
              let newRelVx = relVx + impulseNormal * nx;
              let newRelVy = relVy + impulseNormal * ny;

              // Wall tangential friction
              const tx = -ny;
              const ty = nx;
              const tangVel = relVx * tx + relVy * ty;
              newRelVx -= tangVel * WALL_FRICTION * tx;
              newRelVy -= tangVel * WALL_FRICTION * ty;

              b.vx = wallVx + newRelVx;
              b.vy = wallVy + newRelVy;
            }
          }
        }
      }

      // Ball-to-ball collisions
      for (let i = 0; i < balls.length; i++) {
        for (let j = i + 1; j < balls.length; j++) {
          const b1 = balls[i];
          const b2 = balls[j];
          let dx = b2.x - b1.x;
          let dy = b2.y - b1.y;
          let dist = Math.hypot(dx, dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist && dist > 0) {
            const nx = dx / dist;
            const ny = dy / dist;

            // Separation
            const overlap = (minDist - dist) * 0.5;
            b1.x -= nx * overlap;
            b1.y -= ny * overlap;
            b2.x += nx * overlap;
            b2.y += ny * overlap;

            // Relative velocity along collision line
            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = 2 * (nx * kx + ny * ky) / (b1.mass + b2.mass);

            if (nx * kx + ny * ky > 0) {
              b1.vx -= p * b2.mass * nx * BALL_RESTITUTION;
              b1.vy -= p * b2.mass * ny * BALL_RESTITUTION;
              b2.vx += p * b1.mass * nx * BALL_RESTITUTION;
              b2.vy += p * b1.mass * ny * BALL_RESTITUTION;
            }
          }
        }
      }
    }

    // Render frame
    ctx.clearRect(0, 0, width, height);

    // Draw Hexagon
    const vertices = getHexagonVertices(hexAngle);
    ctx.beginPath();
    ctx.moveTo(vertices[0].x, vertices[0].y);
    for (let i = 1; i < 6; i++) {
      ctx.lineTo(vertices[i].x, vertices[i].y);
    }
    ctx.closePath();

    ctx.fillStyle = '#181c26';
    ctx.fill();

    ctx.strokeStyle = '#5ac8fa';
    ctx.lineWidth = 6;
    ctx.lineJoin = 'round';
    ctx.shadowColor = '#007aff';
    ctx.shadowBlur = 15;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Balls
    for (const b of balls) {
      b.draw();
    }

    requestAnimationFrame(update);
  }

  requestAnimationFrame(update);
</script>
</body>
</html>
```

The animation integrates gravity and damping while using sub-stepped impulse-based collision dynamics to compute momentum-conserving elastic impacts between balls and account for the linear tangential velocity imparted by the spinning hexagon's edges.
